var NL=String.fromCharCode(10);
const trig = $('Telegram Trigger').first().json;
const userMessage = (trig && trig.message && (trig.message.text || trig.message.caption)) || '';
const chatId = trig && trig.message && trig.message.chat ? trig.message.chat.id : null;
const now = new Date();
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Copenhagen',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
const weekday = new Intl.DateTimeFormat('da-DK',{timeZone:'Europe/Copenhagen',weekday:'long',day:'numeric',month:'long'}).format(now);
const nowTime = new Intl.DateTimeFormat('da-DK',{timeZone:'Europe/Copenhagen',hour:'2-digit',minute:'2-digit'}).format(now);
function hm(dt){ return new Date(dt).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Copenhagen'}); }
const calRows = $('Get Calendar Today').all().map(function(i){return i.json;}).filter(function(e){return e && e.start;});
const dayEvents = calRows.filter(function(e){ var d=e.start.dateTime||e.start.date; if(!d) return false; return String(d).slice(0,10)===today; });
var eventsText = dayEvents.length ? dayEvents.map(function(e){ var s=e.start.dateTime?hm(e.start.dateTime):'hele dagen'; var en=e.end&&e.end.dateTime?hm(e.end.dateTime):''; return '- '+s+(en?'-'+en:'')+': '+(e.summary||'(uden titel)'); }).join(NL) : '(ingen møder i kalenderen i dag)';
const memRows = $('Get Memory').all().map(function(i){return i.json;}).filter(function(r){return r && r.content && r.active!==false;});
var memText = memRows.length ? memRows.map(function(r){return '- ['+r.mem_type+'] '+r.content;}).join(NL) : '(ingen gemte præferencer endnu)';
const logRows = $('Get Task Log').all().map(function(i){return i.json;}).filter(function(r){return r && r.task_type && r.estimate_min;});
function actOf(r){ return (r.actual_min!==undefined && r.actual_min!==null && r.actual_min!=='') ? Number(r.actual_min) : null; }
var calib='(ingen historik endnu)';
if(logRows.length){ var by={}; logRows.forEach(function(r){ var v=actOf(r); if(v===null) v=Number(r.estimate_min); (by[r.task_type]=by[r.task_type]||[]).push(v); }); calib=Object.keys(by).map(function(t){ var a=by[t]; var avg=Math.round(a.reduce(function(x,y){return x+y;},0)/a.length); return '- '+t+': typisk '+avg+' min ('+a.length+' registreringer)'; }).join(NL); }
var todaysLogged = logRows.filter(function(r){return r.log_date===today;});
var loggedText = todaysLogged.length ? todaysLogged.map(function(r){ var v=actOf(r); var a=(v===null)?' | faktisk: endnu ikke registreret':(' | faktisk: '+v+' min'); return '- '+r.task+' (type '+r.task_type+', estimat '+r.estimate_min+' min'+a+')'; }).join(NL) : '(ingen loggede opgaver i dag)';
const pendRows = $('Get Pending Plan').all().map(function(i){return i.json;}).filter(function(r){return r && r.plan_json;});
const hasPending = pendRows.length>0;
const pendingText = hasPending ? pendRows[pendRows.length-1].plan_json : '(ingen ventende plan)';
const sp = [
'Du er Daniels personlige assistent og dagsplanlægger. Du er direkte, præcis og handlingsorienteret.',
'Skriv ALTID korrekt dansk med æ, ø og å — aldrig ae/oe/aa.',
'Aktuel tid i København: '+weekday+', kl. '+nowTime+'. Dags dato (ISO): '+today+'.',
'',
'<kontekst>',
'Daniel arbejder med e-mailmarketing og automation (n8n), styrer sine opgaver i et projektværktøj og studerer ved siden af jobbet.',
'</kontekst>',
'',
'<dagens_kalender>',
eventsText,
'</dagens_kalender>',
'',
'<hukommelse>',
memText,
'</hukommelse>',
'',
'<estimat_kalibrering>',
'Historiske tider pr opgavetype (faktisk tid hvor den findes, ellers estimat) — brug til realistiske estimater:',
calib,
'</estimat_kalibrering>',
'',
'<dagens_loggede_opgaver>',
loggedText,
'</dagens_loggede_opgaver>',
'',
'<ventende_plan>',
'Findes der en plan der venter på bekræftelse i dag: '+(hasPending?'JA':'NEJ'),
'Plan-data (JSON): '+pendingText,
'</ventende_plan>',
'',
'<opgave>',
'Klassificer Daniels besked som en af fire hensigter:',
'1. plan = Daniel giver en todo-liste eller beder om at få planlagt sin dag.',
'2. confirm = Daniel bekræfter en ventende plan (fx ja, kør, opret dem). Vælg KUN hvis ventende_plan er JA.',
'3. actuals = Daniel rapporterer hvor lang tid opgaver FAKTISK tog (fx kampagnen tog 2 timer, mails 20 min).',
'4. chat = alt andet.',
'',
'Hvis intent=plan: For HVER opgave: estimer realistisk varighed (brug estimat_kalibrering), giv en kort type (fx kampagne, email, møde-forb, admin, studie, dyb-arbejde), og skemalæg den i et ledigt hul i dag UDENOM eksisterende møder. Kun rimelig dagtid (ca 08:00-18:00), undgå overlap, 10 min buffer, respekter præferencer. Start tidligst fra næste hele eller halve time efter kl. '+nowTime+'. Brug ISO 8601 med tidszone +02:00. I reply: kort forslag med hver blok (klokkeslæt + opgave + estimat), samlet tid, slut med linjen: Svar JA for at lægge dem i kalenderen.',
'Hvis intent=confirm: sæt reply til en kort bekræftelse om at blokkene oprettes.',
'Hvis intent=actuals: match Daniels rapport mod dagens_loggede_opgaver og returner i feltet actuals et array af objekter med task og actual_min, hvor task er det NØJAGTIGE opgavenavn fra dagens_loggede_opgaver og actual_min er heltal minutter (konverter timer til minutter). Sæt reply til en kort kvittering.',
'Hvis intent=chat: besvar normalt i reply.',
'',
'Hvis Daniel udtrykker en varig præference, et arbejdsmønster eller en tilbagevendende opgave, tilføj det i memory_writes.',
'Tilføj IKKE en memory der i forvejen står i <hukommelse> (undgå dubletter).',
'Hvis Daniels besked gør en eksisterende hukommelse forældet eller modsiger den, så list den gamles NØJAGTIGE content-tekst (uden [type]-præfikset) i memory_deactivate, så den kan slukkes.',
'</opgave>',
'',
'<output>',
'Svar KUN med gyldig JSON (ingen markdown udenfor). Brug korrekte danske tegn i reply-feltet. Format:',
'{ "intent":"plan|confirm|actuals|chat", "reply":"tekst (Telegram Markdown: *fed*, _kursiv_)", "plan":[ {"task":"...","type":"...","estimate_min":60,"start":"2026-06-29T09:00:00+02:00","end":"2026-06-29T10:00:00+02:00"} ], "actuals":[ {"task":"...","actual_min":120} ], "memory_writes":[ {"type":"preference|pattern|recurring","content":"..."} ], "memory_deactivate":[ "nøjagtig content-tekst på en forældet memory" ] }',
'Udelad plan/actuals/memory_writes/memory_deactivate (eller sæt tomt array) hvis ikke relevant.',
'</output>'
].join(NL);
return [{ json: { chatId: chatId, today: today, payload: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:2048, system: sp, messages:[{ role:'user', content: userMessage }] }) } }];

const res = $json;
const raw = res && res.content && res.content[0] ? res.content[0].text : '';
var txt = (raw||'').trim();
var fence = String.fromCharCode(96)+String.fromCharCode(96)+String.fromCharCode(96);
if(txt.indexOf(fence)>=0){ var first=txt.indexOf(fence); txt=txt.slice(first+fence.length); if(txt.slice(0,4).toLowerCase()==='json'){ txt=txt.slice(4); } var last=txt.lastIndexOf(fence); if(last>=0){ txt=txt.slice(0,last); } txt=txt.trim(); }
var data;
try { data = JSON.parse(txt); } catch(e){ data = { intent:'chat', reply: (raw || 'Beklager, jeg kunne ikke fortolke svaret. Prøv igen.'), plan:[], actuals:[], memory_writes:[], memory_deactivate:[] }; }
var intent = data.intent || 'chat';
var reply = data.reply || '';
var plan = Array.isArray(data.plan) ? data.plan : [];
var actuals = Array.isArray(data.actuals) ? data.actuals : [];
var mw = Array.isArray(data.memory_writes) ? data.memory_writes : [];
var md = Array.isArray(data.memory_deactivate) ? data.memory_deactivate : [];
const chatId = $('Build Claude Payload').first().json.chatId;
const today = $('Build Claude Payload').first().json.today;
return [{ json: { intent: intent, reply: reply, planJson: JSON.stringify(plan), planCount: plan.length, actualsJson: JSON.stringify(actuals), memoryWrites: mw, memoryDeactivate: md, chatId: String(chatId), today: today } }];

const pendRows = $("Get Pending Plan").all().map(function(i){return i.json;}).filter(function(r){return r && r.plan_json;});
const trig = $("Telegram Trigger").first().json;
const chatId = trig && trig.message && trig.message.chat ? String(trig.message.chat.id) : "";
const today = $("Parse Claude Response").first().json.today;
if(!pendRows.length){ return []; }
var plan=[];
try{ plan = JSON.parse(pendRows[pendRows.length-1].plan_json) || []; }catch(e){ plan=[]; }
var stamp = Date.now().toString(36).slice(-4);
var dateKey = String(today).replace(/-/g,'');
return plan.filter(function(p){return p && p.start && p.end;}).map(function(p, idx){
  return { json: {
    summary: (p.task || "Opgave"),
    description: "Estimeret: "+(p.estimate_min||"?")+" min. Type: "+(p.type||"-")+". Planlagt af din assistent.",
    start: p.start,
    end: p.end,
    task: p.task || "Opgave",
    task_type: p.type || "-",
    estimate_min: Number(p.estimate_min) || 0,
    scheduled_start: p.start,
    log_date: today,
    chatId: chatId,
    created_at: (new Date()).toISOString(),
    task_id: dateKey+"-"+stamp+"-"+idx,
    done: false
  }};
});

const created = $("Create Calendar Event").all().map(function(i){return i.json;}).filter(function(e){return e && (e.id||e.htmlLink||e.start);});
const trig = $("Telegram Trigger").first().json;
const chatId = trig && trig.message && trig.message.chat ? String(trig.message.chat.id) : "";
var lines = created.map(function(e){ var t=""; try{ t=new Date(e.start.dateTime).toLocaleTimeString("da-DK",{hour:"2-digit",minute:"2-digit",timeZone:"Europe/Copenhagen"}); }catch(x){ t=""; } return "- "+(t?t+" ":"")+(e.summary||"Opgave"); }).join("\n");
var text = created.length ? ("Lagt i kalenderen ("+created.length+" blokke):\n"+lines) : "Der var ingen plan at oprette.";
return [{ json: { chatId: chatId, text: text } }];

const mw = $("Parse Claude Response").first().json.memoryWrites || [];
const now = (new Date()).toISOString();
if(!Array.isArray(mw) || !mw.length){ return []; }
return mw.filter(function(m){return m && m.content;}).map(function(m){ return { json: { mem_type: (m.type||"preference"), content: m.content, active: true, created_at: now } }; });

const today = $('Parse Claude Response').first().json.today;
var arr=[];
try{ arr = JSON.parse($('Parse Claude Response').first().json.actualsJson||'[]')||[]; }catch(e){ arr=[]; }
return arr.filter(function(a){return a && a.task && a.actual_min!==undefined && a.actual_min!==null;}).map(function(a){ return { json: { task: String(a.task), actual_min: Number(a.actual_min)||0, log_date: today } }; });

