const md = $("Parse Claude Response").first().json.memoryDeactivate || [];
if(!Array.isArray(md) || !md.length){ return []; }
return md.filter(function(c){return c && String(c).trim();}).map(function(c){ return { json: { content: String(c) } }; });

const trig = $('Telegram Trigger').first().json;
const data = (trig.callback_query && trig.callback_query.data) || '';
const taskId = data.split('|')[1] || '';
const chatId = trig.callback_query && trig.callback_query.message && trig.callback_query.message.chat ? String(trig.callback_query.message.chat.id) : '';
